from django.utils import timezone


def preencher_vencimentos(apps, schema_editor):
    Condominio = apps.get_model('core', 'Condominio')
    for condominio in Condominio.objects.all().iterator():
        if condominio.isento_assinatura or condominio.vencimento_em:
            continue
        referencia = condominio.assinatura_valida_ate or condominio.trial_ate
        if not referencia:
            continue
        vencimento = timezone.localtime(referencia).date()
        condominio.vencimento_em = vencimento
        condominio.dia_vencimento = min(vencimento.day, 28)
        condominio.save(update_fields=['vencimento_em', 'dia_vencimento'])


